/* =========================================================
   HOT POT RESTAURANT
   PART 3 — RESPONSIVE
   MOBILE + IPAD MINI + IPAD PRO + RTL
========================================================= */


/* =========================================================
   01. TABLET / IPAD PRO
   1024px — 1199px
========================================================= */

@media (max-width: 1199px) {

    /* ---------------------------------------------
       HEADER
    --------------------------------------------- */

    .header-container {

        width: min(
            calc(100% - 40px),
            var(--container-width)
        );

        gap: 20px;
    }


    /* ---------------------------------------------
       HIDE DESKTOP NAVIGATION
    --------------------------------------------- */

    .main-navigation {

        display: none;
    }


    /* ---------------------------------------------
       HIDE DESKTOP ACTIONS
    --------------------------------------------- */

    .header-actions {

        display: none;
    }


    /* ---------------------------------------------
       SHOW HAMBURGER
    --------------------------------------------- */

    .hamburger-btn {

        display: flex;

        margin-left: auto;
    }


    /* ---------------------------------------------
       MOBILE MENU
    --------------------------------------------- */

    .mobile-menu {

        position: absolute;

        top: 100%;

        left: 0;

        width: 100%;

        max-height: calc(100vh - var(--header-height));

        overflow-y: auto;

        overflow-x: hidden;

        display: none;

        opacity: 0;

        visibility: hidden;

        transform: translateY(-10px);

        transition:
            opacity var(--transition),
            visibility var(--transition),
            transform var(--transition);

        box-shadow:
            0 15px 35px rgba(0, 0, 0, 0.12);
    }


    /* ---------------------------------------------
       OPEN MOBILE MENU
    --------------------------------------------- */

    .site-header.menu-open .mobile-menu {

        display: block;

        opacity: 1;

        visibility: visible;

        transform: translateY(0);
    }


    /* ---------------------------------------------
       MOBILE MENU INNER
    --------------------------------------------- */

    .mobile-menu-inner {

        width: min(
            calc(100% - 40px),
            760px
        );

        margin: 0 auto;

        padding: 25px 0 30px;
    }


    /* ---------------------------------------------
       MOBILE NAVIGATION
    --------------------------------------------- */

    .mobile-navigation {

        width: 100%;
    }


    .mobile-nav-menu {

        width: 100%;

        display: flex;

        flex-direction: column;

        gap: 2px;
    }


    .mobile-nav-item {

        width: 100%;

        border-bottom: 1px solid var(--border-color);
    }


    /* ---------------------------------------------
       MOBILE NAV LINKS
    --------------------------------------------- */

    .mobile-nav-link {

        position: relative;

        width: 100%;

        min-height: 52px;

        padding: 13px 4px;

        display: flex;

        align-items: center;

        justify-content: space-between;

        gap: 15px;

        color: var(--text-color);

        background: transparent;

        font-size: 15px;

        font-weight: 500;

        text-align: left;

        transition:
            color var(--transition),
            background-color var(--transition);
    }


    .mobile-nav-link:hover {

        color: var(--primary-color);
    }


    /* ---------------------------------------------
       MOBILE HOME DROPDOWN
    --------------------------------------------- */

    .mobile-has-dropdown {

        position: relative;
    }


    .mobile-dropdown-toggle {

        cursor: pointer;
    }


    /* ---------------------------------------------
       MOBILE DROPDOWN ICON
    --------------------------------------------- */

    .mobile-dropdown-icon {

        width: 20px;

        height: 20px;

        flex-shrink: 0;

        display: inline-flex;

        align-items: center;

        justify-content: center;

        transition:
            transform var(--transition);
    }


    .mobile-dropdown-icon i {

        font-size: 10px;
    }


    /* ---------------------------------------------
       MOBILE DROPDOWN
    --------------------------------------------- */

    .mobile-dropdown-menu {

        width: 100%;

        max-height: 0;

        overflow: hidden;

        opacity: 0;

        visibility: hidden;

        padding: 0;

        background-color: var(--section-bg);

        border-radius: var(--radius-sm);

        transition:
            max-height 0.35s ease,
            opacity 0.25s ease,
            visibility 0.25s ease,
            padding 0.25s ease;
    }


    /* OPEN */

    .mobile-has-dropdown.active
    .mobile-dropdown-menu {

        max-height: 150px;

        padding: 5px 0 8px;

        opacity: 1;

        visibility: visible;
    }


    /* ---------------------------------------------
       ROTATE MOBILE DROPDOWN ICON
    --------------------------------------------- */

    .mobile-has-dropdown.active
    .mobile-dropdown-icon {

        transform: rotate(180deg);
    }


    /* ---------------------------------------------
       MOBILE DROPDOWN LINK
    --------------------------------------------- */

    .mobile-dropdown-link {

        width: 100%;

        min-height: 42px;

        padding: 9px 18px;

        display: flex;

        align-items: center;

        color: var(--muted-text);

        font-size: 14px;

        font-weight: 500;

        border-radius: 5px;

        transition:
            color var(--transition),
            background-color var(--transition);
    }


    .mobile-dropdown-link:hover {

        color: var(--primary-color);

        background-color: rgba(
            184,
            74,
            47,
            0.08
        );
    }


    /* ---------------------------------------------
       MOBILE ACTIONS
    --------------------------------------------- */

    .mobile-actions {

        width: 100%;

        margin-top: 22px;

        padding-top: 22px;

        border-top: 1px solid var(--border-color);

        display: grid;

        grid-template-columns: repeat(2, 1fr);

        gap: 10px;
    }


    /* ---------------------------------------------
       MOBILE ACTION BUTTON
    --------------------------------------------- */

    .mobile-action-btn {

        min-height: 44px;

        padding: 10px 15px;

        display: flex;

        align-items: center;

        justify-content: center;

        gap: 8px;

        color: var(--text-color);

        background-color: transparent;

        border: 1px solid var(--border-color);

        border-radius: var(--radius-sm);

        font-size: 13px;

        font-weight: 600;

        text-align: center;

        transition:
            color var(--transition),
            background-color var(--transition),
            border-color var(--transition),
            transform var(--transition);
    }


    .mobile-action-btn:hover {

        color: var(--primary-color);

        border-color: var(--primary-color);

        background-color: rgba(
            184,
            74,
            47,
            0.06
        );
    }


    /* ---------------------------------------------
       MOBILE RTL
    --------------------------------------------- */

    .mobile-rtl-toggle {

        min-width: 0;
    }


    /* ---------------------------------------------
       MOBILE DARK MODE
    --------------------------------------------- */

    .mobile-dark-toggle {

        min-width: 0;
    }


    .mobile-dark-icon {

        width: 18px;

        height: 18px;

        display: inline-flex;

        align-items: center;

        justify-content: center;
    }


    .mobile-dark-icon i {

        font-size: 14px;
    }


    /* ---------------------------------------------
       MOBILE LOGIN
    --------------------------------------------- */

    .mobile-login-btn {

        color: var(--primary-color);

        border-color: var(--primary-color);
    }


    .mobile-login-btn:hover {

        color: var(--white);

        background-color: var(--primary-color);
    }


    /* ---------------------------------------------
       MOBILE DASHBOARD
    --------------------------------------------- */

    .mobile-dashboard-btn {

        color: var(--white);

        background-color: var(--primary-color);

        border-color: var(--primary-color);
    }


    .mobile-dashboard-btn:hover {

        color: var(--white);

        background-color: var(--primary-hover);

        border-color: var(--primary-hover);
    }


    /* ---------------------------------------------
       HAMBURGER ACTIVE
    --------------------------------------------- */

    .site-header.menu-open
    .hamburger-line:nth-child(1) {

        transform:
            translateY(7px)
            rotate(45deg);
    }


    .site-header.menu-open
    .hamburger-line:nth-child(2) {

        opacity: 0;
    }


    .site-header.menu-open
    .hamburger-line:nth-child(3) {

        transform:
            translateY(-7px)
            rotate(-45deg);
    }


    /* ---------------------------------------------
       DARK MODE MOBILE MENU
    --------------------------------------------- */

    body.dark-mode .mobile-menu {

        box-shadow:
            0 15px 40px rgba(0, 0, 0, 0.40);
    }


    body.dark-mode
    .mobile-dropdown-menu {

        background-color: var(--card-bg);
    }


    /* ---------------------------------------------
       PREVENT PAGE SCROLL WHEN OPEN
    --------------------------------------------- */

    body.menu-open {

        overflow: hidden;
    }
}


/* =========================================================
   02. IPAD MINI
   768px — 1024px
========================================================= */

@media (max-width: 1024px) {

    .header-container {

        width: calc(100% - 40px);

        gap: 18px;
    }


    .site-logo img {

        height: var(--logo-height);

        max-width: 210px;
    }


    .mobile-menu-inner {

        width: calc(100% - 40px);

        max-width: 700px;
    }
}


/* =========================================================
   03. MOBILE
   BELOW 767px
========================================================= */

@media (max-width: 767px) {

    /* ---------------------------------------------
       HEADER
    --------------------------------------------- */

    :root {

        --header-height: 74px;

        --logo-height: 52px;
    }


    .header-container {

        width: calc(100% - 30px);

        gap: 15px;
    }


    /* ---------------------------------------------
       LOGO
    --------------------------------------------- */

    .site-logo {

        flex: 1;

        justify-content: flex-start;

        min-width: 0;
    }


    .site-logo img {

        height: var(--logo-height);

        max-width: 200px;
    }


    /* ---------------------------------------------
       HAMBURGER
    --------------------------------------------- */

    .hamburger-btn {

        width: 43px;

        height: 43px;

        margin-left: auto;

        flex-shrink: 0;
    }


    /* ---------------------------------------------
       MOBILE MENU
    --------------------------------------------- */

    .mobile-menu {

        max-height: calc(100vh - 74px);
    }


    .mobile-menu-inner {

        width: calc(100% - 30px);

        padding: 20px 0 25px;
    }


    /* ---------------------------------------------
       NAV
    --------------------------------------------- */

    .mobile-nav-link {

        min-height: 50px;

        padding: 12px 2px;

        font-size: 14px;
    }


    .mobile-dropdown-link {

        font-size: 13px;

        padding-left: 16px;

        padding-right: 16px;
    }


    /* ---------------------------------------------
       ACTIONS
    --------------------------------------------- */

    .mobile-actions {

        grid-template-columns: 1fr 1fr;

        gap: 8px;

        margin-top: 18px;

        padding-top: 18px;
    }


    .mobile-action-btn {

        min-height: 43px;

        padding: 9px 10px;

        font-size: 12px;
    }
}


/* =========================================================
   04. SMALL MOBILE
   BELOW 480px
========================================================= */

@media (max-width: 480px) {

    :root {

        --header-height: 70px;

        --logo-height: 49px;
    }


    .header-container {

        width: calc(100% - 24px);

        gap: 10px;
    }


    .site-logo img {

        height: var(--logo-height);

        max-width: 180px;
    }


    .hamburger-btn {

        width: 42px;

        height: 42px;
    }


    .mobile-menu {

        max-height: calc(100vh - 70px);
    }


    .mobile-menu-inner {

        width: calc(100% - 24px);

        padding-top: 17px;

        padding-bottom: 22px;
    }


    .mobile-nav-link {

        min-height: 48px;

        font-size: 14px;
    }


    .mobile-actions {

        gap: 7px;
    }


    .mobile-action-btn {

        min-height: 42px;

        padding: 8px 7px;

        font-size: 11px;
    }
}


/* =========================================================
   05. VERY SMALL MOBILE
   BELOW 360px
========================================================= */

@media (max-width: 359px) {

    .site-logo img {

        max-width: 165px;
    }


    .hamburger-btn {

        width: 40px;

        height: 40px;
    }


    .mobile-action-btn {

        font-size: 10px;

        padding-left: 5px;

        padding-right: 5px;
    }
}


/* =========================================================
   06. RTL — TABLET / MOBILE
========================================================= */

@media (max-width: 1199px) {

    /* ---------------------------------------------
       HEADER DIRECTION
    --------------------------------------------- */

    html[dir="rtl"] .header-container {

        direction: rtl;
    }


    /* ---------------------------------------------
       HAMBURGER POSITION
    --------------------------------------------- */

    html[dir="rtl"] .hamburger-btn {

        margin-left: 0;

        margin-right: auto;
    }


    /* ---------------------------------------------
       LOGO POSITION
    --------------------------------------------- */

    html[dir="rtl"] .site-logo {

        justify-content: flex-end;
    }


    /* ---------------------------------------------
       MOBILE MENU
    --------------------------------------------- */

    html[dir="rtl"] .mobile-menu {

        left: auto;

        right: 0;

        text-align: right;
    }


    html[dir="rtl"] .mobile-menu-inner {

        direction: rtl;
    }


    /* ---------------------------------------------
       NAVIGATION
    --------------------------------------------- */

    html[dir="rtl"] .mobile-nav-menu {

        direction: rtl;
    }


    html[dir="rtl"] .mobile-nav-link {

        text-align: right;

        direction: rtl;
    }


    /* ---------------------------------------------
       HOME DROPDOWN
    --------------------------------------------- */

    html[dir="rtl"]
    .mobile-dropdown-menu {

        direction: rtl;
    }


    html[dir="rtl"]
    .mobile-dropdown-link {

        text-align: right;

        padding-right: 18px;

        padding-left: 18px;
    }


    /* ---------------------------------------------
       ACTIONS
    --------------------------------------------- */

    html[dir="rtl"] .mobile-actions {

        direction: rtl;
    }


    html[dir="rtl"] .mobile-action-btn {

        direction: rtl;

        text-align: center;
    }
}


/* =========================================================
   07. RTL MOBILE DROPDOWN ICON
========================================================= */

@media (max-width: 1199px) {

    html[dir="rtl"]
    .mobile-dropdown-toggle {

        flex-direction: row;
    }


    html[dir="rtl"]
    .mobile-dropdown-icon {

        margin-left: 0;

        margin-right: 0;
    }
}


/* =========================================================
   08. DARK MODE RESPONSIVE
========================================================= */

@media (max-width: 1199px) {

    body.dark-mode
    .mobile-action-btn {

        background-color: transparent;

        border-color: var(--border-color);

        color: var(--text-color);
    }


    body.dark-mode
    .mobile-action-btn:hover {

        color: var(--primary-color);

        background-color: rgba(
            215,
            101,
            67,
            0.10
        );

        border-color: var(--primary-color);
    }


    body.dark-mode
    .mobile-dashboard-btn {

        color: var(--white);

        background-color: var(--primary-color);

        border-color: var(--primary-color);
    }


    body.dark-mode
    .mobile-login-btn {

        color: var(--primary-color);

        border-color: var(--primary-color);
    }
}


/* =========================================================
   09. SCROLLBAR FOR MOBILE MENU
========================================================= */

@media (max-width: 1199px) {

    .mobile-menu::-webkit-scrollbar {

        width: 5px;
    }


    .mobile-menu::-webkit-scrollbar-track {

        background: transparent;
    }


    .mobile-menu::-webkit-scrollbar-thumb {

        background-color: var(--border-color);

        border-radius: 10px;
    }


    .mobile-menu {

        scrollbar-width: thin;

        scrollbar-color:
            var(--border-color)
            transparent;
    }
}


/* =========================================================
   10. LANDSCAPE MOBILE
========================================================= */

@media (max-width: 767px) and (orientation: landscape) {

    .mobile-menu {

        max-height: calc(100vh - 74px);
    }


    .mobile-menu-inner {

        padding-top: 12px;

        padding-bottom: 15px;
    }


    .mobile-nav-link {

        min-height: 44px;

        padding-top: 8px;

        padding-bottom: 8px;
    }


    .mobile-actions {

        margin-top: 12px;

        padding-top: 12px;
    }
}


/* =========================================================
   11. ACCESSIBILITY
========================================================= */

@media (prefers-reduced-motion: reduce) {

    .mobile-menu,
    .mobile-dropdown-menu,
    .mobile-dropdown-icon,
    .hamburger-line {

        transition: none !important;
    }
}










