        font-size: 16px;
    }

    .footer-links a {
        font-size: 13px;
    }

    .footer-contact-item p,
    .footer-contact-item a {
        font-size: 12px;
    }

    .footer-newsletter {
        gap: 25px;
    }

    .footer-newsletter-form {
        min-width: 340px;
    }

}


/* =========================================================
   IPAD PRO
   768px – 991px
========================================================= */

@media (max-width: 991px) {

    .footer-container {
        width: calc(100% - 48px);
    }


    /* ---------------------------------------------
       FOOTER TOP
    --------------------------------------------- */

    .footer-top {
        grid-template-columns: 1.2fr 1fr 1fr;

        gap: 45px 35px;

        padding: 65px 0 50px;
    }


    /* Brand gets complete first row */

    .footer-brand {
        grid-column: 1 / -1;

        max-width: 600px;
    }

    .footer-description {
        max-width: 540px;
    }


    /* ---------------------------------------------
       LOGO
    --------------------------------------------- */

    .footer-logo img {
        height: 52px;
    }


    /* ---------------------------------------------
       NEWSLETTER
    --------------------------------------------- */

    .footer-newsletter {
        flex-direction: column;

        align-items: stretch;

        gap: 22px;

        padding: 28px 0;
    }

    .footer-newsletter-content {
        width: 100%;
    }

    .footer-newsletter-form {
        width: 100%;

        min-width: 0;

        max-width: 600px;
    }


    /* ---------------------------------------------
       FOOTER BOTTOM
    --------------------------------------------- */

    .footer-bottom {
        min-height: auto;

        padding: 22px 0;

        flex-direction: column;

        align-items: center;

        justify-content: center;

        gap: 10px;

        text-align: center;
    }

}


